import java.util.Scanner;

public class Main {
    public static int findPattern(String str, String pattern, int startIndex) {
        for (int i = startIndex; i <= str.length() - pattern.length(); i++) {
            if (str.charAt(i) == pattern.charAt(0)) {
                boolean match = true;
                for (int j = 1; j < pattern.length(); j++) {
                    if (str.charAt(i + j) != pattern.charAt(j)) {
                        match = false;
                        break;
                    }
                }
                if (match) return i;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.nextLine();
        StringBuilder outputStr = new StringBuilder();

        int atIndex = findPattern(inputStr, "at", 1);
        String modifiedStr;
        if (atIndex != -1) {
            modifiedStr = inputStr.substring(0, atIndex) + '@' + inputStr.substring(atIndex + 2);
        } else {
            modifiedStr = inputStr;
        }

        int dotIndex = findPattern(modifiedStr, "dot", 1);
        int start = 0;
        while (dotIndex != -1 && dotIndex < modifiedStr.length() - 3) {
            outputStr.append(modifiedStr.substring(start, dotIndex)).append(".");
            start = dotIndex + 3;
            dotIndex = findPattern(modifiedStr, "dot", start);
        }
        outputStr.append(modifiedStr.substring(start));
        System.out.println(outputStr.toString());
        scanner.close();
    }
}
